INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload) VALUES('core-2026-09-v3','past-modals','e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4','{"slug":"past-modals","title":"Past deductions, criticism and unnecessary actions","level":"B2","order":41,"summary":"Use modal perfect forms to look back at possibilities, missed opportunities and actions that were unnecessary.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["Deductions about the past","Criticism and regret","Past possibility and opportunity","No need versus an unnecessary completed action"],"rules":[{"title":"Deductions about the past","explanation":"Use **modal + have + past participle** to evaluate an earlier event. Must have suggests a strong positive conclusion; can’t have suggests impossibility; might have leaves it uncertain. Have remains base form after every modal and every subject.","pattern":"She **must have left**. / They **might have missed** it.","commonMistakes":["Must had and must has are not standard modal-perfect forms."],"examples":["Make a past deduction: “She must **have prepared** the visitor guide before we arrived.”","Make a past deduction: “She must **have restored** the old portrait before we arrived.”"],"skill":"form"},{"title":"Criticism and regret","explanation":"Should have + past participle can describe a desirable action that did not happen, or an expectation about a completed event. Context decides which. Should not have often criticises an action that did happen.","pattern":"You **should have called**; we were worried.","commonMistakes":["Should have is not always blame: the parcel should have arrived by now can express an expectation."],"examples":["The task was not done, but doing it was advisable: “You **should** have prepared the visitor guide.”","The task was not done, but doing it was advisable: “You **should** have restored the old portrait.”"],"skill":"meaning"},{"title":"Past possibility and opportunity","explanation":"Could have may refer to a past possibility or an unrealised opportunity. Might have can express uncertainty about whether something happened. Read the context carefully before deciding whether the sentence states an actual event.","pattern":"We **could have stayed**, but we chose to leave.","commonMistakes":["Could have stayed does not by itself say that the person stayed."],"examples":["You did the task, but it was unnecessary: “You **need not** have prepared the visitor guide.”","You did the task, but it was unnecessary: “You **need not** have restored the old portrait.”"],"skill":"contrast"},{"title":"No need versus an unnecessary completed action","explanation":"Needn’t have + participle usually says an action happened but was unnecessary. Didn’t need to says there was no necessity and does not, by itself, settle whether the action happened. This meaning difference matters when offering reassurance.","pattern":"You **needn’t have waited**; I had a key.","commonMistakes":["Didn’t need to wait does not automatically mean that the person waited."],"examples":["Infer an ongoing past activity: “At that time, they might have **been preparing** the visitor guide.”","Infer an ongoing past activity: “At that time, they might have **been restoring** the old portrait.”"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-past-deduction"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"quizItems":[{"id":"ffb57b90-5b20-5ac2-af45-2b1e2e2b7480","topicSlug":"past-modals","level":"B2","prompt":"Make a past deduction: “She must ____ the visitor guide before we arrived.”","choices":[{"id":"A","text":"had prepared"},{"id":"B","text":"have preparing"},{"id":"C","text":"have prepared"},{"id":"D","text":"has prepared"}],"answerId":"C","hint":"Build **modal + have + past participle**.","explanation":"The past deduction requires **must have prepared**. Have stays base after must.","keywords":["past-deduction-form"],"skill":"past-deduction-form","contextKey":"past-modals-1","fingerprint":"b8b46702e6a2d8a2f9b82eae0eec5e0220a3eb6ca182e29aa4b50b25105b87f5","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-past-deduction"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Build **modal + have + past participle**.","The past deduction requires **must have prepared**. Have stays base after must.","Choose **have prepared**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Had cannot directly follow must.","B":"Have needs a past participle in this simple modal-perfect construction.","C":"The past deduction requires **must have prepared**. Have stays base after must.","D":"Has cannot follow a central modal."}}},{"id":"46a0e965-003d-5d3e-a9ff-a9313b5e9dca","topicSlug":"past-modals","level":"B2","prompt":"The task was not done, but doing it was advisable: “You ____ have prepared the visitor guide.”","choices":[{"id":"A","text":"should"},{"id":"B","text":"must"},{"id":"C","text":"will"},{"id":"D","text":"can"}],"answerId":"A","hint":"The clue is **advisable but not done**, pointing to should have.","explanation":"**Should have** marks the desirable action that the context says did not happen.","keywords":["past-criticism"],"skill":"past-criticism","contextKey":"past-modals-1","fingerprint":"dc0ee44de97746f16a60514bbc734428f3fc57088bc5a9accd0dd9bc9871c73d","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-past-deduction"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The clue is **advisable but not done**, pointing to should have.","**Should have** marks the desirable action that the context says did not happen.","Choose **should**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"**Should have** marks the desirable action that the context says did not happen.","B":"Must have would claim a strong deduction that it happened, contradicting the context.","C":"Will have would express a different prediction or inference, not the requested retrospective advice.","D":"Can have does not make the normal retrospective-advice pattern."}}},{"id":"1520d85c-0051-5b9f-ac0c-956329f727ac","topicSlug":"past-modals","level":"B2","prompt":"You did the task, but it was unnecessary: “You ____ have prepared the visitor guide.”","choices":[{"id":"A","text":"need not"},{"id":"B","text":"must not"},{"id":"C","text":"did not need"},{"id":"D","text":"should"}],"answerId":"A","hint":"The action **happened**, and the speaker says there was **no need** for it.","explanation":"**Need not have** says the completed action was unnecessary.","keywords":["unnecessary-completed-action"],"skill":"unnecessary-completed-action","contextKey":"past-modals-1","fingerprint":"a21524c5b4e6029264065e52dd36806b6755a84b85c01634ad1e7369e39e3193","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-past-deduction"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The action **happened**, and the speaker says there was **no need** for it.","**Need not have** says the completed action was unnecessary.","Choose **need not**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"**Need not have** says the completed action was unnecessary.","B":"Must not have does not express the stated lack of necessity in this construction.","C":"Did not need requires to before have and is not the needn’t-have pattern.","D":"Should have would recommend the action, not say it was unnecessary."}}},{"id":"7c9bfdcb-ad2e-5b35-a359-c6d056b60466","topicSlug":"past-modals","level":"B2","prompt":"Infer an ongoing past activity: “At that time, they might have ____ the visitor guide.”","choices":[{"id":"A","text":"be preparing"},{"id":"B","text":"preparing"},{"id":"C","text":"been preparing"},{"id":"D","text":"being preparing"}],"answerId":"C","hint":"Combine past possibility with continuous aspect: **might have been + -ing**.","explanation":"After might have, use **been preparing** to refer to an activity in progress at that past time.","keywords":["past-continuous-deduction"],"skill":"past-continuous-deduction","contextKey":"past-modals-1","fingerprint":"88aa5497066e576b2476afa7a2858b99db793a09b412df9e72aee0e3b6568ef0","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-past-deduction"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Combine past possibility with continuous aspect: **might have been + -ing**.","After might have, use **been preparing** to refer to an activity in progress at that past time.","Choose **been preparing**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Base be cannot follow perfect have.","B":"Been is missing between have and the -ing form.","C":"After might have, use **been preparing** to refer to an activity in progress at that past time.","D":"Have requires the participle been, not being."}}},{"id":"881a371b-9d7b-5824-ade7-85b3e1f15632","topicSlug":"past-modals","level":"B2","prompt":"Make a past deduction: “She must ____ the old portrait before we arrived.”","choices":[{"id":"A","text":"had restored"},{"id":"B","text":"have restoring"},{"id":"C","text":"have restored"},{"id":"D","text":"has restored"}],"answerId":"C","hint":"Build **modal + have + past participle**.","explanation":"The past deduction requires **must have restored**. Have stays base after must.","keywords":["past-deduction-form"],"